+import { MOCK_DEFAULT_ORGANIZATION_MEMBER, MOCK_DEFAULT_USER, MOCK_SECOND_ORGANIZATION_MEMBER } from 'lib/api.mock'
+
+import { expectLogic } from 'kea-test-utils'
+
+import { userLogic } from 'scenes/userLogic'
+
+import { useMocks } from '~/mocks/jest'
+import { initKeaTests } from '~/test/init'
+
+import { inviteLogic } from './inviteLogic'
+
+describe('inviteLogic', () => {
+    let logic: ReturnType<typeof inviteLogic.build>
+
+    beforeEach(async () => {
+        useMocks({
+            get: {
+                '/api/organizations/:organization/members/': {
+                    count: 2,
+                    next: null,
+                    previous: null,
+                    results: [MOCK_SECOND_ORGANIZATION_MEMBER, MOCK_DEFAULT_ORGANIZATION_MEMBER],
+                },
+            },
+        })
+        initKeaTests()
+        userLogic().mount()
+        await expectLogic(userLogic).toMatchValues({
+            user: expect.objectContaining({ email: MOCK_DEFAULT_USER.email }),
+        })
+        logic = inviteLogic()
+        logic.mount()
+    })
+
+    it.each([
+        ['an existing member, in a different case', MOCK_SECOND_ORGANIZATION_MEMBER.user.email.toUpperCase(), true],
+        ['the own email of the user', MOCK_DEFAULT_USER.email, true],
+        ['a new email', 'new-teammate@example.com', false],
+    ])('handles a batch that contains %s', async (_desc, email, isFlagged) => {
+        await expectLogic(logic, () => {
+            logic.actions.updateInviteAtIndex({ target_email: 'first-teammate@example.com', isValid: true }, 0)
+            logic.actions.appendInviteRow()
+            logic.actions.updateInviteAtIndex({ target_email: email, isValid: true }, 1)
+        }).toFinishAllListeners()
+
+        expect(logic.values.inviteRowErrors[0]).toBeNull()
+        expect(!!logic.values.inviteRowErrors[1]).toBe(isFlagged)
+        expect(logic.values.canSubmit).toBe(!isFlagged)
+    })
+})
